using Microsoft.EntityFrameworkCore;using TechnifyERP.Application.Settings;using TechnifyERP.Domain.Entities;using TechnifyERP.Infrastructure.Persistence;
namespace TechnifyERP.Infrastructure.Settings;
internal sealed class AcademySettingsService(ApplicationDbContext db):IAcademySettingsService
{public async Task<AcademySettingsDto>GetAsync(CancellationToken ct=default){var x=await db.AcademySettings.AsNoTracking().OrderBy(x=>x.Id).FirstOrDefaultAsync(ct);return x is null?new AcademySettingsDto("Technify ERP","TechnifyERP",null,$"{DateTime.Today.Year}-{DateTime.Today.Year+1}",null,null,null):new AcademySettingsDto(x.AcademyName,x.ShortName,x.Website,x.AcademicYear,x.Email,x.Phone,x.Address);}public async Task<SettingsActionResult>SaveAsync(AcademySettingsDto r,CancellationToken ct=default){if(string.IsNullOrWhiteSpace(r.AcademyName)||string.IsNullOrWhiteSpace(r.ShortName)||string.IsNullOrWhiteSpace(r.AcademicYear))return SettingsActionResult.Invalid;var x=await db.AcademySettings.OrderBy(x=>x.Id).FirstOrDefaultAsync(ct);if(x is null){x=new AcademySettings();db.Add(x);}x.AcademyName=r.AcademyName.Trim();x.ShortName=r.ShortName.Trim();x.Website=Clean(r.Website);x.AcademicYear=r.AcademicYear.Trim();x.Email=Clean(r.Email);x.Phone=Clean(r.Phone);x.Address=Clean(r.Address);x.UpdatedAtUtc=DateTime.UtcNow;await db.SaveChangesAsync(ct);return SettingsActionResult.Success;}private static string?Clean(string?x)=>string.IsNullOrWhiteSpace(x)?null:x.Trim();}
